solution.code:
import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const a = second.split(" ").map(Number);

// 2 で割り切れるものだけ残して数える
const evens = a.filter((x) => x % 2 === 0);
console.log(evens.length);
